-- Leonida Vice Guide: more pin types (shop, property, activity) and a pin source.
-- NOT YET APPLIED to any database. The app works without it: it selects `source` only when the
-- column exists (src/lib/map/store/supabase.ts) and always shows the seed pins from seed-pins.json.
-- Idempotent: safe to re-run.

-- 1. Pin source: 'official' = named by Rockstar, 'community' = marked by a player, 'gtadb' = imported from GTADB.org (CC BY 4.0).
alter table public.pins add column if not exists source text not null default 'community';
alter table public.pins drop constraint if exists pins_source_check;
alter table public.pins add constraint pins_source_check check (source in ('official', 'community', 'gtadb'));
update public.pins set source = 'official' where is_seed and source <> 'official';
create index if not exists pins_source_idx on public.pins (source);

-- 2. New pin types.
alter table public.pins drop constraint if exists pins_type_check;
alter table public.pins add constraint pins_type_check
  check (type in ('region', 'landmark', 'shop', 'property', 'activity', 'secret', 'collectible', 'quest', 'other'));

-- 3. Submissions may use the new types; they are always stored as source = 'community'.
create or replace function public.submit_location(
  p_type text,
  p_name text,
  p_description text,
  p_region text,
  p_occupant text,
  p_x double precision,
  p_y double precision,
  p_gamer_tag text,
  p_spoiler boolean,
  p_ip_hash text,
  p_window_minutes integer default 60
) returns public.pins
language plpgsql
set search_path = public
as $$
declare
  v_last timestamptz;
  v_row public.pins;
begin
  if p_type not in ('landmark', 'shop', 'property', 'activity', 'secret', 'collectible', 'quest', 'other') then
    raise exception 'INVALID: type';
  end if;
  if char_length(btrim(coalesce(p_description, ''))) < 20 then
    raise exception 'INVALID: description';
  end if;
  if char_length(btrim(coalesce(p_name, ''))) < 3 or char_length(btrim(coalesce(p_gamer_tag, ''))) < 2 then
    raise exception 'INVALID: required field';
  end if;

  -- Serialise submissions per gamer tag so two parallel requests can't both pass the check.
  perform pg_advisory_xact_lock(hashtext('lvg-submit:' || lower(p_gamer_tag)));

  select max(created_at) into v_last
  from public.pins
  where gamer_tag_lc = lower(p_gamer_tag)
    and not is_seed
    and created_at > now() - make_interval(mins => p_window_minutes);

  if v_last is not null then
    raise exception 'RATE_LIMITED:%',
      greatest(1, ceil(extract(epoch from (v_last + make_interval(mins => p_window_minutes) - now())) / 60))::int;
  end if;

  insert into public.pins (status, type, name, description, region, occupant, x, y, gamer_tag, spoiler, ip_hash, source)
  values ('pending', p_type, btrim(p_name), btrim(p_description), p_region, p_occupant, p_x, p_y, btrim(p_gamer_tag),
          coalesce(p_spoiler, false), p_ip_hash, 'community')
  returning * into v_row;
  return v_row;
end;
$$;

